use std::sync::{Arc, Condvar, Mutex};
use std::thread;

struct Shared {
    m1: Mutex<()>,
    m2: Mutex<()>,
    cv: Condvar,
    announced: Mutex<i32>,
    done: Mutex<i32>,
}

fn main() {
    let shared = Arc::new(Shared {
        m1: Mutex::new(()),
        m2: Mutex::new(()),
        cv: Condvar::new(),
        announced: Mutex::new(0),
        done: Mutex::new(0),
    });

    let s1 = Arc::clone(&shared);
    let h1 = thread::spawn(move || waiter1(s1));

    let s2 = Arc::clone(&shared);
    let h2 = thread::spawn(move || waiter2(s2));

    let s3 = Arc::clone(&shared);
    let h3 = thread::spawn(move || notifier(s3));

    h1.join().unwrap();
    h2.join().unwrap();
    h3.join().unwrap();

    let d = *shared.done.lock().unwrap();
    println!("DONE done={}", d);
}

fn waiter1(shared: Arc<Shared>) {
    let _g1 = shared.m1.lock().unwrap();

    let a = *shared.announced.lock().unwrap();
    let a2 = a + 1;
    *shared.announced.lock().unwrap() = a2;

    let _g1 = shared.cv.wait(_g1).unwrap();

    let d = *shared.done.lock().unwrap();
    let d2 = d + 1;
    *shared.done.lock().unwrap() = d2;
}

fn waiter2(shared: Arc<Shared>) {
    let g2 = shared.m2.lock().unwrap();

    {
        let _g1 = shared.m1.lock().unwrap();
        let a = *shared.announced.lock().unwrap();
        let a2 = a + 1;
        *shared.announced.lock().unwrap() = a2;
    }

    let g2 = shared.cv.wait(g2).unwrap();

    {
        let _g1 = shared.m1.lock().unwrap();
        let d = *shared.done.lock().unwrap();
        let d2 = d + 1;
        *shared.done.lock().unwrap() = d2;
    }

    drop(g2);
}

fn notifier(shared: Arc<Shared>) {
    let g1 = shared.m1.lock().unwrap();

    loop {
        let a = *shared.announced.lock().unwrap();
        if a == 2 {
            break;
        }
        drop(g1);
        thread::yield_now();
        let g1 = shared.m1.lock().unwrap();
        let a = *shared.announced.lock().unwrap();
        if a == 2 {
            let g2 = shared.m2.lock().unwrap();
            shared.cv.notify_all();
            drop(g2);
            drop(g1);
            return;
        }
        drop(g1);
    }

    let g2 = shared.m2.lock().unwrap();
    shared.cv.notify_all();
    drop(g2);
    drop(g1);
}
